import Foundation
import AppKit

enum SpotifyError: LocalizedError {
    case invalidCredentials
    case networkError(String)
    case invalidResponse
    case authenticationFailed(String)
    case playlistCreationFailed(String)
    case tokenExpired

    var errorDescription: String? {
        switch self {
        case .invalidCredentials:
            return "Invalid Spotify credentials. Please check your configuration."
        case .networkError(let message):
            return "Network error: \(message)"
        case .invalidResponse:
            return "Invalid response from Spotify API"
        case .authenticationFailed(let message):
            return "Authentication failed: \(message)"
        case .playlistCreationFailed(let message):
            return "Failed to create playlist: \(message)"
        case .tokenExpired:
            return "Spotify authentication token expired. Please reconnect."
        }
    }
}

@Observable
class SpotifyService {
    static let shared = SpotifyService()

    private let clientId: String
    private let clientSecret: String
    private let redirectUri: String
    private let baseURL = "https://api.spotify.com/v1"
    private let authURL = "https://accounts.spotify.com"

    var accessToken: String? {
        didSet {
            if accessToken != nil {
                UserDefaults.standard.set(accessToken, forKey: "spotifyAccessToken")
            }
        }
    }
    var tokenExpirationDate: Date?
    var isAuthenticated: Bool { accessToken != nil && !isTokenExpired() }
    var currentUser: SpotifyUser?

    init() {
        self.clientId = ProcessInfo.processInfo.environment["SPOTIPY_CLIENT_ID"] ?? ""
        self.clientSecret = ProcessInfo.processInfo.environment["SPOTIPY_CLIENT_SECRET"] ?? ""
        self.redirectUri = ProcessInfo.processInfo.environment["SPOTIPY_REDIRECT_URI"] ?? "pulse://spotify/callback"

        // Load saved token if available
        if let savedToken = UserDefaults.standard.string(forKey: "spotifyAccessToken") {
            self.accessToken = savedToken
        }
    }

    // MARK: - Authentication

    func startOAuthFlow(completion: @escaping (Result<String, SpotifyError>) -> Void) {
        let scopes = [
            "playlist-modify-public",
            "playlist-modify-private",
            "user-library-read",
            "user-read-private",
            "user-read-email",
            "user-top-read"
        ].joined(separator: "%20")

        let authString = "\(clientId):\(clientSecret)"
        guard let authData = authString.data(using: .utf8) else {
            completion(.failure(.invalidCredentials))
            return
        }

        let authBase64 = authData.base64EncodedString()

        var urlComponents = URLComponents(string: "\(authURL)/authorize")!
        urlComponents.queryItems = [
            URLQueryItem(name: "client_id", value: clientId),
            URLQueryItem(name: "response_type", value: "code"),
            URLQueryItem(name: "redirect_uri", value: redirectUri),
            URLQueryItem(name: "scope", value: scopes),
            URLQueryItem(name: "show_dialog", value: "true")
        ]

        guard let url = urlComponents.url else {
            completion(.failure(.authenticationFailed("Invalid URL")))
            return
        }

        // Open in default browser
        NSWorkspace.shared.open(url)
        completion(.success("Authorization started. Waiting for callback..."))
    }

    func exchangeCodeForToken(_ code: String, completion: @escaping (Result<Void, SpotifyError>) -> Void) {
        let authString = "\(clientId):\(clientSecret)"
        guard let authData = authString.data(using: .utf8) else {
            completion(.failure(.invalidCredentials))
            return
        }

        let authBase64 = authData.base64EncodedString()

        var request = URLRequest(url: URL(string: "\(authURL)/api/token")!)
        request.httpMethod = "POST"
        request.setValue("Basic \(authBase64)", forHTTPHeaderField: "Authorization")
        request.setValue("application/x-www-form-urlencoded", forHTTPHeaderField: "Content-Type")

        var components = URLComponents()
        components.queryItems = [
            URLQueryItem(name: "grant_type", value: "authorization_code"),
            URLQueryItem(name: "code", value: code),
            URLQueryItem(name: "redirect_uri", value: redirectUri)
        ]

        request.httpBody = components.percentEncodedQuery?.data(using: .utf8)

        URLSession.shared.dataTask(with: request) { [weak self] data, response, error in
            if let error = error {
                completion(.failure(.networkError(error.localizedDescription)))
                return
            }

            guard let data = data else {
                completion(.failure(.invalidResponse))
                return
            }

            do {
                let tokenResponse = try JSONDecoder().decode(TokenResponse.self, from: data)
                DispatchQueue.main.async {
                    self?.accessToken = tokenResponse.access_token
                    self?.tokenExpirationDate = Date().addingTimeInterval(TimeInterval(tokenResponse.expires_in))
                    completion(.success(()))
                }
            } catch {
                completion(.failure(.authenticationFailed(error.localizedDescription)))
            }
        }.resume()
    }

    // MARK: - API Methods

    func getCurrentUser(completion: @escaping (Result<SpotifyUser, SpotifyError>) -> Void) {
        guard isAuthenticated else {
            completion(.failure(.tokenExpired))
            return
        }

        makeRequest(endpoint: "/me", method: "GET", completion: completion)
    }

    func getLikedTracks(limit: Int = 50, offset: Int = 0, completion: @escaping (Result<[PulseTrack], SpotifyError>) -> Void) {
        guard isAuthenticated else {
            completion(.failure(.tokenExpired))
            return
        }

        let endpoint = "/me/tracks?limit=\(limit)&offset=\(offset)"
        makeRequest(endpoint: endpoint, method: "GET") { (result: Result<TracksResponse, SpotifyError>) in
            switch result {
            case .success(let response):
                let tracks = response.items.map { PulseTrack(from: $0.track) }
                completion(.success(tracks))
            case .failure(let error):
                completion(.failure(error))
            }
        }
    }

    func getRecentTracks(limit: Int = 50, completion: @escaping (Result<[PulseTrack], SpotifyError>) -> Void) {
        guard isAuthenticated else {
            completion(.failure(.tokenExpired))
            return
        }

        let endpoint = "/me/player/recently_played?limit=\(limit)"
        makeRequest(endpoint: endpoint, method: "GET") { (result: Result<RecentlyPlayedResponse, SpotifyError>) in
            switch result {
            case .success(let response):
                let tracks = response.items.map { PulseTrack(from: $0.track) }
                completion(.success(tracks))
            case .failure(let error):
                completion(.failure(error))
            }
        }
    }

    func searchTracks(query: String, limit: Int = 20, completion: @escaping (Result<[PulseTrack], SpotifyError>) -> Void) {
        guard isAuthenticated else {
            completion(.failure(.tokenExpired))
            return
        }

        let encodedQuery = query.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? query
        let endpoint = "/search?q=\(encodedQuery)&type=track&limit=\(limit)"

        makeRequest(endpoint: endpoint, method: "GET") { (result: Result<SearchResponse, SpotifyError>) in
            switch result {
            case .success(let response):
                let tracks = response.tracks.items.map { PulseTrack(from: $0) }
                completion(.success(tracks))
            case .failure(let error):
                completion(.failure(error))
            }
        }
    }

    func createPlaylist(name: String, description: String, isPublic: Bool, tracks: [PulseTrack], completion: @escaping (Result<String, SpotifyError>) -> Void) {
        guard isAuthenticated, let userId = currentUser?.id else {
            completion(.failure(.tokenExpired))
            return
        }

        let endpoint = "/users/\(userId)/playlists"
        let body: [String: Any] = [
            "name": name,
            "description": description,
            "public": isPublic
        ]

        makeRequest(endpoint: endpoint, method: "POST", body: body) { (result: Result<PlaylistResponse, SpotifyError>) in
            switch result {
            case .success(let playlist):
                // Add tracks to playlist
                self.addTracksToPlaylist(playlistId: playlist.id, tracks: tracks) { addResult in
                    switch addResult {
                    case .success:
                        completion(.success(playlist.id))
                    case .failure(let error):
                        completion(.failure(error))
                    }
                }
            case .failure(let error):
                completion(.failure(error))
            }
        }
    }

    private func addTracksToPlaylist(playlistId: String, tracks: [PulseTrack], completion: @escaping (Result<Void, SpotifyError>) -> Void) {
        let trackUris = tracks.map { $0.uri }.filter { !$0.isEmpty }
        guard !trackUris.isEmpty else {
            completion(.success(()))
            return
        }

        let endpoint = "/playlists/\(playlistId)/tracks"
        let body: [String: Any] = ["uris": trackUris]

        makeRequest(endpoint: endpoint, method: "POST", body: body) { (result: Result<AddTracksResponse, SpotifyError>) in
            switch result {
            case .success:
                completion(.success(()))
            case .failure(let error):
                completion(.failure(error))
            }
        }
    }

    // MARK: - Private Methods

    private func makeRequest<T: Decodable>(endpoint: String, method: String = "GET", body: [String: Any]? = nil, completion: @escaping (Result<T, SpotifyError>) -> Void) {
        guard let token = accessToken else {
            completion(.failure(.tokenExpired))
            return
        }

        let url = URL(string: baseURL + endpoint)!
        var request = URLRequest(url: url)
        request.httpMethod = method
        request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        if let body = body {
            request.httpBody = try? JSONSerialization.data(withJSONObject: body)
        }

        URLSession.shared.dataTask(with: request) { data, response, error in
            if let error = error {
                DispatchQueue.main.async {
                    completion(.failure(.networkError(error.localizedDescription)))
                }
                return
            }

            guard let data = data else {
                DispatchQueue.main.async {
                    completion(.failure(.invalidResponse))
                }
                return
            }

            do {
                let decoder = JSONDecoder()
                decoder.dateDecodingStrategy = .iso8601
                let decodedResponse = try decoder.decode(T.self, from: data)
                DispatchQueue.main.async {
                    completion(.success(decodedResponse))
                }
            } catch {
                DispatchQueue.main.async {
                    completion(.failure(.authenticationFailed(error.localizedDescription)))
                }
            }
        }.resume()
    }

    private func isTokenExpired() -> Bool {
        guard let expirationDate = tokenExpirationDate else { return true }
        return Date() >= expirationDate
    }

    func logout() {
        accessToken = nil
        tokenExpirationDate = nil
        currentUser = nil
        UserDefaults.standard.removeObject(forKey: "spotifyAccessToken")
    }
}

// MARK: - Codable Models

struct TokenResponse: Codable {
    let access_token: String
    let token_type: String
    let expires_in: Int
    let refresh_token: String?
}

struct SpotifyUser: Codable, Identifiable {
    let id: String
    let display_name: String?
    let email: String?
    let external_urls: [String: String]?
    let followers: Followers?
    let href: String?
    let images: [Image]?
    let uri: String?
}

struct Followers: Codable {
    let href: String?
    let total: Int?
}

struct Image: Codable {
    let height: Int?
    let url: String?
    let width: Int?
}

struct TracksResponse: Codable {
    let items: [SavedTrack]
}

struct SavedTrack: Codable {
    let track: Track
}

struct Track: Codable {
    let id: String
    let name: String
    let artists: [Artist]
    let uri: String
    let audio_features: AudioFeatures?
}

struct Artist: Codable {
    let id: String
    let name: String
}

struct AudioFeatures: Codable {
    let energy: Double?
    let valence: Double?
    let tempo: Double?
    let genres: [String]?
}

struct RecentlyPlayedResponse: Codable {
    let items: [PlayHistory]
}

struct PlayHistory: Codable {
    let track: Track
    let played_at: String?
}

struct SearchResponse: Codable {
    let tracks: TracksWrapper
}

struct TracksWrapper: Codable {
    let items: [Track]
}

struct PlaylistResponse: Codable {
    let id: String
    let name: String
    let description: String?
    let public: Bool
    let uri: String
}

struct AddTracksResponse: Codable {
    let snapshot_id: String
}

