import Foundation

struct PulsePlaylist: Identifiable, Codable {
    let id: String
    let name: String
    let description: String
    var tracks: [PulseTrack]
    let createdAt: Date
    let isPublic: Bool
    let spotifyUrl: String?
}

struct PulseTrack: Identifiable, Codable, Hashable {
    let id: String
    let name: String
    let artist: String
    let energy: Double?
    let valence: Double?
    let tempo: Int?
    let genre: String?
    let uri: String
    let spotifyId: String

    init(id: String, name: String, artist: String, energy: Double? = nil, valence: Double? = nil, tempo: Int? = nil, genre: String? = nil, uri: String = "", spotifyId: String = "") {
        self.id = id
        self.name = name
        self.artist = artist
        self.energy = energy
        self.valence = valence
        self.tempo = tempo
        self.genre = genre
        self.uri = uri
        self.spotifyId = spotifyId
    }

    // Initialize from Spotify Track
    init(from track: Track) {
        self.id = track.id
        self.name = track.name
        self.artist = track.artists.first?.name ?? "Unknown Artist"
        self.energy = track.audio_features?.energy
        self.valence = track.audio_features?.valence
        self.tempo = Int(track.audio_features?.tempo ?? 0)
        self.genre = track.audio_features?.genres?.first
        self.uri = track.uri
        self.spotifyId = track.id
    }
}

@Observable
class PlaylistManager {
    var playlists: [PulsePlaylist] = []
    var isLoading = false
    var error: String?
    private let spotifyService = SpotifyService.shared

    func createPlaylist(name: String, tracks: [PulseTrack], isPublic: Bool) {
        guard !tracks.isEmpty else {
            error = "Cannot create playlist with no tracks"
            return
        }

        isLoading = true
        error = nil

        spotifyService.createPlaylist(
            name: name,
            description: "Created with PULSE",
            isPublic: isPublic,
            tracks: tracks
        ) { [weak self] result in
            DispatchQueue.main.async {
                self?.isLoading = false

                switch result {
                case .success(let playlistId):
                    let playlist = PulsePlaylist(
                        id: playlistId,
                        name: name,
                        description: "Created with PULSE",
                        tracks: tracks,
                        createdAt: Date(),
                        isPublic: isPublic,
                        spotifyUrl: "https://open.spotify.com/playlist/\(playlistId)"
                    )
                    self?.playlists.append(playlist)

                case .failure(let error):
                    self?.error = error.errorDescription ?? "Failed to create playlist"
                }
            }
        }
    }

    func deletePlaylist(id: String) {
        playlists.removeAll { $0.id == id }
    }
}

