                    .background(Color(red: 0.05, green: 0.1, blue: 0.12))
                    .cornerRadius(6)
                    .padding(.horizontal, 16)

                    // Source Options
                    VStack(alignment: .leading, spacing: 8) {
                        Text("📚 Include Tracks From")
                            .font(.system(size: 12, weight: .semibold, design: .monospaced))
                            .foregroundColor(Color(red: 0.0, green: 0.94, blue: 1.0))

                        Toggle(isOn: $useLikedTracks) {
                            Text("Your Liked Tracks")
                                .font(.system(size: 11, design: .monospaced))
                                .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))
                        }
                        .tint(Color(red: 0.0, green: 1.0, blue: 0.8))

                        Toggle(isOn: $useRecentTracks) {
                            Text("Recently Played")
                                .font(.system(size: 11, design: .monospaced))
                                .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))
                        }
                        .tint(Color(red: 0.0, green: 1.0, blue: 0.8))
                    }
                    .padding(12)
                    .background(Color(red: 0.05, green: 0.1, blue: 0.12))
                    .cornerRadius(6)
                    .padding(.horizontal, 16)

                    // Privacy Option
                    VStack(alignment: .leading, spacing: 8) {
                        Toggle(isOn: $makePublic) {
                            Text("Make Playlist Public")
                                .font(.system(size: 11, design: .monospaced))
                                .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))
                        }
                        .tint(Color(red: 0.0, green: 1.0, blue: 0.8))
                    }
                    .padding(12)
                    .background(Color(red: 0.05, green: 0.1, blue: 0.12))
                    .cornerRadius(6)
                    .padding(.horizontal, 16)

                    // Error Message
                    if let error = playlistManager.error {
                        Text(error)
                            .font(.system(size: 11, design: .monospaced))
                            .foregroundColor(.red)
                            .padding(10)
                            .background(Color(red: 0.2, green: 0.0, blue: 0.0))
                            .cornerRadius(4)
                            .padding(.horizontal, 16)
                    }

                    // Create Button
                    Button(action: createPlaylist) {
                        HStack {
                            if playlistManager.isLoading {
                                ProgressView()
                                    .progressViewStyle(CircularProgressViewStyle(tint: .black))
                            }
                            Text(playlistManager.isLoading ? "Creating..." : "💚 Create Playlist 💙")
                                .font(.system(size: 12, weight: .semibold, design: .monospaced))
                        }
                        .frame(maxWidth: .infinity)
                        .padding(.vertical, 10)
                        .background(Color(red: 0.0, green: 1.0, blue: 0.8))
                        .foregroundColor(Color(red: 0.02, green: 0.04, blue: 0.05))
                        .cornerRadius(6)
                    }
                    .disabled(playlistManager.isLoading || playlistName.isEmpty)
                    .padding(.horizontal, 16)

                    Spacer()
                }
                .padding(.vertical, 8)
            }
        }
    }

    private func toggleGenre(_ genre: String) {
        if selectedGenres.contains(genre) {
            selectedGenres.remove(genre)
        } else {
            selectedGenres.insert(genre)
        }
    }

    private func createPlaylist() {
        // Create mock tracks for now (will be populated from Spotify in full implementation)
        let mockTracks = (0..<30).map { i in
            PulseTrack(
                id: UUID().uuidString,
                name: "Track \(i + 1)",
                artist: "Artist \(i + 1)",
                energy: energyLevel,
                valence: moodLevel,
                tempo: Int(60 + (energyLevel * 140)),
                genre: selectedGenres.first ?? "Electronic",
                uri: "spotify:track:mock\(i)",
                spotifyId: "mock\(i)"
            )
        }

        playlistManager.createPlaylist(
            name: playlistName,
            tracks: mockTracks,
            isPublic: makePublic
        )
    }
}

