                        .padding(12)
                    }
                }
            }
        }
    }
}

// MARK: - Playlist Card

struct PlaylistCard: View {
    let playlist: PulsePlaylist
    @State private var isHovering = false

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            // Header
            HStack(alignment: .top) {
                VStack(alignment: .leading, spacing: 4) {
                    Text(playlist.name)
                        .font(.system(size: 13, weight: .semibold, design: .monospaced))
                        .foregroundColor(Color(red: 0.0, green: 0.94, blue: 1.0))

                    HStack(spacing: 12) {
                        Label("\(playlist.tracks.count) songs", systemImage: "music.note")
                            .font(.system(size: 10, design: .monospaced))
                            .foregroundColor(Color(red: 0.42, green: 0.6, blue: 0.6))

                        Label(playlist.isPublic ? "Public" : "Private", systemImage: playlist.isPublic ? "globe" : "lock")
                            .font(.system(size: 10, design: .monospaced))
                            .foregroundColor(Color(red: 0.42, green: 0.6, blue: 0.6))
                    }
                }

                Spacer()

                // Created Date
                VStack(alignment: .trailing, spacing: 4) {
                    Image(systemName: "calendar")
                        .font(.system(size: 12))
                        .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))

                    Text(playlist.createdAt.formatted(date: .abbreviated, time: .omitted))
                        .font(.system(size: 9, design: .monospaced))
                        .foregroundColor(Color(red: 0.42, green: 0.6, blue: 0.6))
                }
            }

            Divider()
                .background(Color(red: 0.0, green: 0.8, blue: 0.8, opacity: 0.1))

            // Actions
            HStack(spacing: 8) {
                // Open in Spotify
                if let spotifyUrl = playlist.spotifyUrl {
                    Link(destination: URL(string: spotifyUrl)!) {
                        Label("Open in Spotify", systemImage: "link")
                            .font(.system(size: 10, design: .monospaced))
                            .padding(6)
                            .frame(maxWidth: .infinity)
                            .background(Color(red: 0.18, green: 0.96, blue: 0.3))
                            .foregroundColor(Color(red: 0.02, green: 0.04, blue: 0.05))
                            .cornerRadius(4)
                    }
                }

                // Copy Spotify Link
                Button(action: { copySpotifyLink() }) {
                    Label("Copy Link", systemImage: "doc.on.doc")
                        .font(.system(size: 10, design: .monospaced))
                        .padding(6)
                        .frame(maxWidth: .infinity)
                        .background(Color(red: 0.08, green: 0.12, blue: 0.15))
                        .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))
                        .cornerRadius(4)
                }
            }
        }
        .padding(12)
        .background(Color(red: 0.05, green: 0.1, blue: 0.12))
        .cornerRadius(6)
        .onHover { hovering in
            isHovering = hovering
        }
    }

    private func copySpotifyLink() {
        if let spotifyUrl = playlist.spotifyUrl {
            NSPasteboard.general.clearContents()
            NSPasteboard.general.setString(spotifyUrl, forType: .string)
        }
    }
}

