import SwiftUI

struct SettingsView: View {
    @Environment(SpotifyService.self) var spotifyService
    @Environment(ConfigService.self) var configService
    @Environment(HeartRateModel.self) var heartRateModel

    @State private var showLogoutConfirmation = false
    @State private var showAbout = false

    var body: some View {
        ZStack {
            Color(red: 0.02, green: 0.04, blue: 0.05)
                .ignoresSafeArea()

            ScrollView {
                VStack(spacing: 16) {
                    // Header
                    VStack(spacing: 8) {
                        Text("⚙️ Settings")
                            .font(.system(size: 18, weight: .bold, design: .monospaced))
                            .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))

                        Text("Configure PULSE")
                            .font(.system(size: 11, design: .monospaced))
                            .foregroundColor(Color(red: 0.42, green: 0.6, blue: 0.6))
                    }
                    .padding(.horizontal, 16)
                    .padding(.top, 12)

                    // Account Section
                    SettingsSectionHeader(title: "👤 Account")

                    VStack(spacing: 12) {
                        if let user = spotifyService.currentUser {
                            VStack(alignment: .leading, spacing: 8) {
                                Text("Spotify Account")
                                    .font(.system(size: 12, weight: .semibold, design: .monospaced))
                                    .foregroundColor(Color(red: 0.0, green: 0.94, blue: 1.0))

                                HStack {
                                    Image(systemName: "person.circle.fill")
                                        .font(.system(size: 14))
                                        .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))

                                    VStack(alignment: .leading, spacing: 2) {
                                        Text(user.display_name ?? "Spotify User")
                                            .font(.system(size: 11, design: .monospaced))
                                            .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))

                                        if let email = user.email {
                                            Text(email)
                                                .font(.system(size: 9, design: .monospaced))
                                                .foregroundColor(Color(red: 0.42, green: 0.6, blue: 0.6))
                                        }
                                    }

                                    Spacer()

                                    Image(systemName: "checkmark.circle.fill")
                                        .font(.system(size: 12))
                                        .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))
                                }
                                .padding(10)
                                .background(Color(red: 0.05, green: 0.15, blue: 0.12))
                                .cornerRadius(4)
                            }
                        }

                        Button(action: { showLogoutConfirmation = true }) {
                            Label("Disconnect Spotify", systemImage: "power")
                                .font(.system(size: 11, weight: .semibold, design: .monospaced))
                                .frame(maxWidth: .infinity)
                                .padding(.vertical, 8)
                                .background(Color(red: 0.2, green: 0.0, blue: 0.0))
                                .foregroundColor(Color(red: 1.0, green: 0.4, blue: 0.4))
                                .cornerRadius(4)
