                                    Text("Heart Rate Monitoring")
                                        .font(.system(size: 11, weight: .semibold, design: .monospaced))
                                        .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))

                                    Text("Use Apple Health for recommendations")
                                        .font(.system(size: 9, design: .monospaced))
                                        .foregroundColor(Color(red: 0.42, green: 0.6, blue: 0.6))
                                }
                            }
                        }
                        .tint(Color(red: 0.0, green: 1.0, blue: 0.8))
                        .padding(10)
                        .background(Color(red: 0.05, green: 0.1, blue: 0.12))
                        .cornerRadius(4)

                        if heartRateModel.isMonitoring {
                            VStack(alignment: .leading, spacing: 8) {
                                Text("User Information")
                                    .font(.system(size: 10, weight: .semibold, design: .monospaced))
                                    .foregroundColor(Color(red: 0.42, green: 0.6, blue: 0.6))

                                HStack {
                                    Text("Age:")
                                        .font(.system(size: 10, design: .monospaced))
                                        .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))

                                    Spacer()

                                    Text("\(heartRateModel.userAge)")
                                        .font(.system(size: 10, weight: .semibold, design: .monospaced))
                                        .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))
                                }

                                HStack {
                                    Text("Resting HR:")
                                        .font(.system(size: 10, design: .monospaced))
                                        .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))

                                    Spacer()

                                    Text("\(heartRateModel.restingHeartRate) BPM")
                                        .font(.system(size: 10, weight: .semibold, design: .monospaced))
                                        .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))
                                }

                                HStack {
                                    Text("Current HR:")
                                        .font(.system(size: 10, design: .monospaced))
