                                    Spacer()

                                    Text("\(heartRateModel.currentHeartRate) BPM")
                                        .font(.system(size: 10, weight: .semibold, design: .monospaced))
                                        .foregroundColor(Color(red: 1.0, green: 0.4, blue: 0.4))
                                }
                            }
                            .padding(10)
                            .background(Color(red: 0.05, green: 0.08, blue: 0.12))
                            .cornerRadius(4)
                        }
                    }
                    .padding(.horizontal, 16)

                    // Playlist Settings
                    SettingsSectionHeader(title: "🎵 Playlist Defaults")

                    VStack(spacing: 12) {
                        Toggle(isOn: $configService.includeLiked) {
                            Text("Include Liked Tracks")
                                .font(.system(size: 11, design: .monospaced))
                                .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))
                        }
                        .tint(Color(red: 0.0, green: 1.0, blue: 0.8))

                        Toggle(isOn: $configService.includeRecent) {
                            Text("Include Recently Played")
                                .font(.system(size: 11, design: .monospaced))
                                .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))
                        }
                        .tint(Color(red: 0.0, green: 1.0, blue: 0.8))

                        Toggle(isOn: $configService.makePublic) {
                            Text("Make Playlists Public by Default")
                                .font(.system(size: 11, design: .monospaced))
                                .foregroundColor(Color(red: 0.88, green: 1.0, blue: 1.0))
                        }
                        .tint(Color(red: 0.0, green: 1.0, blue: 0.8))
                    }
                    .padding(10)
                    .background(Color(red: 0.05, green: 0.1, blue: 0.12))
                    .cornerRadius(4)
                    .padding(.horizontal, 16)

                    // App Info
                    SettingsSectionHeader(title: "ℹ️ App Information")

                    VStack(spacing: 8) {
                        SettingsInfoRow(label: "App Name", value: "PULSE")
                        SettingsInfoRow(label: "Version", value: "1.0.0")
                        SettingsInfoRow(label: "Build", value: "1")
                        SettingsInfoRow(label: "macOS Target", value: "12.0+")
                    }
                    .padding(10)
                    .background(Color(red: 0.05, green: 0.1, blue: 0.12))
                    .cornerRadius(4)
                    .padding(.horizontal, 16)

                    // Links
                    VStack(spacing: 8) {
                        Link(destination: URL(string: "https://www.pulse-music.app")!) {
                            Label("Website", systemImage: "globe")
                                .font(.system(size: 11, design: .monospaced))
                                .frame(maxWidth: .infinity)
                                .padding(.vertical, 8)
                                .background(Color(red: 0.08, green: 0.12, blue: 0.15))
                                .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))
                                .cornerRadius(4)
                        }

                        Link(destination: URL(string: "https://www.pulse-music.app/privacy")!) {
                            Label("Privacy Policy", systemImage: "lock")
                                .font(.system(size: 11, design: .monospaced))
                                .frame(maxWidth: .infinity)
                                .padding(.vertical, 8)
                                .background(Color(red: 0.08, green: 0.12, blue: 0.15))
                                .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))
                                .cornerRadius(4)
                        }

                        Link(destination: URL(string: "https://www.pulse-music.app/terms")!) {
                            Label("Terms of Service", systemImage: "doc.text")
                                .font(.system(size: 11, design: .monospaced))
                                .frame(maxWidth: .infinity)
                                .padding(.vertical, 8)
                                .background(Color(red: 0.08, green: 0.12, blue: 0.15))
                                .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))
                                .cornerRadius(4)
                        }
                    }
                    .padding(.horizontal, 16)
                    .padding(.bottom, 12)
                }
            }
        }
        .confirmationDialog("Disconnect Spotify?", isPresented: $showLogoutConfirmation) {
            Button("Disconnect", role: .destructive) {
                spotifyService.logout()
            }
            Button("Cancel", role: .cancel) { }
        } message: {
            Text("You'll need to reconnect to your Spotify account to continue using PULSE.")
        }
    }
}

